// Simulates one unit travelling down Line 3.
// In production, replace this with your PLC / MES / test-rig
// connections (OPC UA, Modbus, MQTT, REST...) - the record
// format stays exactly the same.
function gauss() {
    let u = 0, v = 0;
    while (!u) u = Math.random();
    while (!v) v = Math.random();
    return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * v);
}

const PARTS = [
    { pn: 'EWP-2201-A', lots: ['LOT-A-1042', 'LOT-A-1043', 'LOT-A-1044'] },
    { pn: 'EWP-2201-B', lots: ['LOT-B-2210', 'LOT-B-2211', 'LOT-B-2212'] }
];

const STATIONS = [
    { station: 'OP10', operation: 'Rotor press',     gauge: 'PRS-010', calDue: '2026-11-30', m: 'press_force_kn', nom: 8.5,  lsl: 7.5,  usl: 9.5,  sd: 0.32, pFail: 0.004 },
    { station: 'OP20', operation: 'Housing torque',  gauge: 'TQW-020', calDue: '2026-08-02', m: 'torque_nm',      nom: 12.0, lsl: 10.8, usl: 13.2, sd: 0.42, pFail: 0.007 },
    { station: 'OP30', operation: 'Leak test',       gauge: 'LKT-030', calDue: '2026-09-15', m: 'leak_rate_sccm', nom: 1.2,  lsl: 0.0,  usl: 3.0,  sd: 0.50, pFail: 0.020 },
    { station: 'OP40', operation: 'EOL performance', gauge: 'EOL-040', calDue: '2027-01-20', m: 'flow_rate_lpm',  nom: 21.0, lsl: 19.0, usl: 23.0, sd: 0.60, pFail: 0.006 }
];

const DEFECTS = {
    OP10: ['PRS-01', 'Press force outside specification'],
    OP20: ['TRQ-02', 'Housing bolt torque outside specification'],
    OP30: ['LEAK-01', 'Leak rate above upper limit'],
    OP40: ['EOL-03', 'Flow performance outside specification']
};

const ROSTER = { A: ['OP-114', 'OP-127', 'OP-133'], B: ['OP-208', 'OP-214', 'OP-221'], C: ['OP-301', 'OP-322'] };

const now = new Date();
const hour = now.getHours();
const shift = (hour >= 6 && hour < 14) ? 'A' : (hour >= 14 && hour < 22) ? 'B' : 'C';
const ops = ROSTER[shift];

const n = (context.get('unitCount') || 0) + 1;
context.set('unitCount', n);

const part = PARTS[n % PARTS.length];
const ymd = now.toISOString().slice(2, 10).replace(/-/g, '');
const serial = part.pn.replace(/-/g, '') + '-' + ymd + '-' + String(n).padStart(5, '0');
const workOrder = 'WO-' + ymd + '-' + shift + '-' + part.pn.slice(-1);
const lot = part.lots[Math.floor(n / 40) % part.lots.length];
const operator = ops[n % ops.length];

const events = [];
let ncMsg = null;

for (let i = 0; i < STATIONS.length; i++) {
    const s = STATIONS[i];
    // Unit moved down the line over the last ~3 minutes
    const ts = new Date(now.getTime() - (STATIONS.length - 1 - i) * 45000).toISOString();

    let value = s.nom + gauss() * s.sd;
    if (Math.random() < s.pFail) {
        value = (s.lsl > 0 && Math.random() < 0.4)
            ? s.lsl - (0.1 + Math.random() * 0.4)
            : s.usl + (0.1 + Math.random() * 0.5);
    }
    value = Math.round(value * 1000) / 1000;
    const pass = value >= s.lsl && value <= s.usl;

    events.push({
        queryParameters: {
            ts, serial, part: part.pn, wo: workOrder,
            station: s.station, operation: s.operation,
            operator, shift, lot,
            gauge: s.gauge, cal_due: s.calDue,
            mname: s.m, mvalue: value, lsl: s.lsl, usl: s.usl,
            result: pass ? 'PASS' : 'FAIL'
        }
    });

    if (!pass) {
        const d = DEFECTS[s.station];
        const closed = Math.random() < 0.5;
        ncMsg = {
            queryParameters: {
                ts, serial, station: s.station,
                code: d[0], descr: d[1],
                dispo: closed ? 'Reworked and retested' : 'Contained - MRB review',
                status: closed ? 'closed' : 'open'
            }
        };
        break; // unit is pulled from the line
    }
}

node.status({ fill: ncMsg ? 'red' : 'green', shape: 'dot', text: serial + (ncMsg ? ' FAIL' : ' PASS') });
return [events, ncMsg ? [ncMsg] : []];

// One-click backfill: seeds ~24 h of history so the stats,
// chart and tables look realistic straight away. Safe to re-run
// (each run adds another batch with unique serials).
function gauss() {
    let u = 0, v = 0;
    while (!u) u = Math.random();
    while (!v) v = Math.random();
    return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * v);
}

const PARTS = [
    { pn: 'EWP-2201-A', lots: ['LOT-A-1042', 'LOT-A-1043', 'LOT-A-1044'] },
    { pn: 'EWP-2201-B', lots: ['LOT-B-2210', 'LOT-B-2211', 'LOT-B-2212'] }
];
const STATIONS = [
    { station: 'OP10', operation: 'Rotor press',     gauge: 'PRS-010', calDue: '2026-11-30', m: 'press_force_kn', nom: 8.5,  lsl: 7.5,  usl: 9.5,  sd: 0.32, pFail: 0.004 },
    { station: 'OP20', operation: 'Housing torque',  gauge: 'TQW-020', calDue: '2026-08-02', m: 'torque_nm',      nom: 12.0, lsl: 10.8, usl: 13.2, sd: 0.42, pFail: 0.007 },
    { station: 'OP30', operation: 'Leak test',       gauge: 'LKT-030', calDue: '2026-09-15', m: 'leak_rate_sccm', nom: 1.2,  lsl: 0.0,  usl: 3.0,  sd: 0.50, pFail: 0.020 },
    { station: 'OP40', operation: 'EOL performance', gauge: 'EOL-040', calDue: '2027-01-20', m: 'flow_rate_lpm',  nom: 21.0, lsl: 19.0, usl: 23.0, sd: 0.60, pFail: 0.006 }
];
const DEFECTS = {
    OP10: ['PRS-01', 'Press force outside specification'],
    OP20: ['TRQ-02', 'Housing bolt torque outside specification'],
    OP30: ['LEAK-01', 'Leak rate above upper limit'],
    OP40: ['EOL-03', 'Flow performance outside specification']
};
const ROSTER = { A: ['OP-114', 'OP-127', 'OP-133'], B: ['OP-208', 'OP-214', 'OP-221'], C: ['OP-301', 'OP-322'] };

const q = v => "'" + String(v).replace(/'/g, "''") + "'";
const nowMs = Date.now();
const peRows = [];
const qeRows = [];
let count = context.get('backfillCount') || 0;
const UNITS = 450;

for (let u = 0; u < UNITS; u++) {
    count++;
    const born = nowMs - Math.floor(Math.random() * 24 * 3600 * 1000);
    const d = new Date(born);
    const hour = d.getHours();
    const shift = (hour >= 6 && hour < 14) ? 'A' : (hour >= 14 && hour < 22) ? 'B' : 'C';
    const ops = ROSTER[shift];
    const part = PARTS[count % PARTS.length];
    const ymd = d.toISOString().slice(2, 10).replace(/-/g, '');
    const serial = part.pn.replace(/-/g, '') + '-' + ymd + '-B' + String(count).padStart(5, '0');
    const workOrder = 'WO-' + ymd + '-' + shift + '-' + part.pn.slice(-1);
    const lot = part.lots[Math.floor(count / 40) % part.lots.length];
    const operator = ops[count % ops.length];

    for (let i = 0; i < STATIONS.length; i++) {
        const s = STATIONS[i];
        const ts = new Date(born + i * 45000).toISOString();
        let value = s.nom + gauss() * s.sd;
        if (Math.random() < s.pFail) {
            value = (s.lsl > 0 && Math.random() < 0.4)
                ? s.lsl - (0.1 + Math.random() * 0.4)
                : s.usl + (0.1 + Math.random() * 0.5);
        }
        value = Math.round(value * 1000) / 1000;
        const pass = value >= s.lsl && value <= s.usl;

        peRows.push('(' + [q(ts), q(serial), q(part.pn), q(workOrder), q(s.station), q(s.operation),
            q(operator), q(shift), q(lot), q(s.gauge), q(s.calDue), q(s.m),
            value, s.lsl, s.usl, q(pass ? 'PASS' : 'FAIL')].join(',') + ')');

        if (!pass) {
            const def = DEFECTS[s.station];
            const closed = Math.random() < 0.5;
            qeRows.push('(' + [q(ts), q(serial), q(s.station), q(def[0]), q(def[1]),
                q(closed ? 'Reworked and retested' : 'Contained - MRB review'),
                q(closed ? 'closed' : 'open')].join(',') + ')');
            break;
        }
    }
}
context.set('backfillCount', count);

const msgs = [];
const CHUNK = 200;
const PE_COLS = '(ts, serial_number, part_number, work_order, station, operation, operator_id, shift, material_lot, gauge_id, gauge_cal_due, measurement_name, measurement_value, lsl, usl, result)';
for (let i = 0; i < peRows.length; i += CHUNK) {
    msgs.push({ query: 'INSERT INTO process_events ' + PE_COLS + ' VALUES ' + peRows.slice(i, i + CHUNK).join(',') + ';' });
}
if (qeRows.length) {
    msgs.push({ query: 'INSERT INTO quality_events (ts, serial_number, station, defect_code, description, disposition, status) VALUES ' + qeRows.join(',') + ';' });
}
node.status({ fill: 'blue', shape: 'dot', text: UNITS + ' units backfilled (' + qeRows.length + ' NCs)' });
return [msgs];

msg.serial = msg.req.params.serial;
msg.query = `SELECT to_char(p.ts, 'YYYY-MM-DD HH24:MI:SS') AS time,
       p.part_number, p.work_order, p.station, p.operation,
       p.operator_id, p.shift,
       p.measurement_name, p.measurement_value, p.lsl, p.usl, p.result,
       p.material_lot, m.supplier, m.heat_number, m.cert_reference,
       p.gauge_id, to_char(p.gauge_cal_due, 'YYYY-MM-DD') AS gauge_cal_due
FROM process_events p
LEFT JOIN material_lots m ON m.lot_id = p.material_lot
WHERE p.serial_number = $1
ORDER BY p.ts`;
msg.params = [msg.serial];
return msg;

msg.trace = msg.payload;
msg.query = 'SELECT to_char(ts, \'YYYY-MM-DD HH24:MI:SS\') AS time, station, defect_code, description, disposition, status FROM quality_events WHERE serial_number = $1 ORDER BY ts';
msg.params = [msg.serial];
return msg;

msg.payload = {
    serial_number: msg.serial,
    generated_at: new Date().toISOString(),
    process_history: msg.trace || [],
    quality_events: msg.payload || []
};
msg.headers = { 'Content-Type': 'application/json' };
msg.statusCode = (msg.trace && msg.trace.length) ? 200 : 404;
return msg;

const days = Math.max(1, Math.min(365, parseInt(msg.req.query.days, 10) || 1));
const part = msg.req.query.part;
let where = `p.ts > now() - interval '${days} days'`;
msg.params = [];
if (part) { where += ' AND p.part_number = $1'; msg.params = [part]; }
msg.query = `SELECT p.serial_number, p.part_number, p.work_order,
       to_char(p.ts, 'YYYY-MM-DD HH24:MI:SS') AS timestamp_utc,
       p.station, p.operation, p.operator_id, p.shift,
       p.material_lot, m.supplier, m.heat_number, m.cert_reference,
       p.gauge_id, to_char(p.gauge_cal_due, 'YYYY-MM-DD') AS gauge_cal_due,
       p.measurement_name, p.measurement_value, p.lsl, p.usl, p.result
FROM process_events p
LEFT JOIN material_lots m ON m.lot_id = p.material_lot
WHERE ${where}
ORDER BY p.ts`;
return msg;

const rows = msg.payload || [];
const cols = rows.length ? Object.keys(rows[0]) : ['no_records'];
const esc = v => {
    v = (v === null || v === undefined) ? '' : String(v);
    return /[",\n]/.test(v) ? '"' + v.replace(/"/g, '""') + '"' : v;
};
const lines = [cols.join(',')];
for (const r of rows) lines.push(cols.map(c => esc(r[c])).join(','));
msg.payload = lines.join('\n');
msg.headers = {
    'Content-Type': 'text/csv',
    'Content-Disposition': 'attachment; filename="line3-audit-evidence.csv"'
};
msg.statusCode = 200;
return msg;

const r = (msg.payload && msg.payload[0]) || {};
const num = v => (v === null || v === undefined) ? null : Number(v);
msg.payload = {
    units_started_24h: num(r.units_started_24h) || 0,
    fpy_pct: num(r.fpy_pct),
    defect_ppm_ops: num(r.defect_ppm_ops),
    open_ncs: num(r.open_ncs) || 0,
    trace_coverage_pct: num(r.trace_coverage_pct),
    gauges_cal_due_30d: num(r.gauges_cal_due_30d) || 0
};
return msg;

const serial = String(msg.payload || '').trim();
if (!serial) return null;
msg.query = `SELECT to_char(p.ts, 'YYYY-MM-DD HH24:MI:SS') AS time,
       p.station, p.operation,
       p.measurement_name AS measurement, p.measurement_value AS value,
       concat(p.lsl, ' - ', p.usl) AS spec, p.result,
       p.operator_id AS operator, p.material_lot,
       m.heat_number, m.supplier, m.cert_reference,
       p.gauge_id, to_char(p.gauge_cal_due, 'YYYY-MM-DD') AS gauge_cal_due
FROM process_events p
LEFT JOIN material_lots m ON m.lot_id = p.material_lot
WHERE p.serial_number = $1
ORDER BY p.ts`;
msg.params = [serial];
return msg;

msg.topic = 'FPY %';
msg.payload = (msg.payload || []).map(r => ({ x: Number(r.x), y: Number(r.y) }));
return msg;

// Tool args arrive in msg.payload per the input schema
const serial = String((msg.payload && msg.payload.serial_number) || '').trim();
if (!serial) {
    msg.payload = { error: 'serial_number is required' };
    return [null, msg]; // straight to response
}
msg.serial = serial;
msg.query = `SELECT to_char(p.ts, 'YYYY-MM-DD HH24:MI:SS') AS time,
       p.part_number, p.work_order, p.station, p.operation,
       p.operator_id, p.shift,
       p.measurement_name, p.measurement_value, p.lsl, p.usl, p.result,
       p.material_lot, m.supplier, m.heat_number, m.cert_reference,
       p.gauge_id, to_char(p.gauge_cal_due, 'YYYY-MM-DD') AS gauge_cal_due
FROM process_events p
LEFT JOIN material_lots m ON m.lot_id = p.material_lot
WHERE p.serial_number = $1
ORDER BY p.ts`;
msg.params = [serial];
return [msg, null];

msg.trace = msg.payload;
msg.query = 'SELECT to_char(ts, \'YYYY-MM-DD HH24:MI:SS\') AS time, station, defect_code, description, disposition, status FROM quality_events WHERE serial_number = $1 ORDER BY ts';
msg.params = [msg.serial];
return msg;

msg.payload = {
    serial_number: msg.serial,
    found: !!(msg.trace && msg.trace.length),
    process_history: msg.trace || [],
    quality_events: msg.payload || []
};
return msg;

// Used by both the get_topline_audit_stats tool and the topline resource.
// Tool args in msg.payload; resource requests carry no args -> default 24 h.
let hours = Number(msg.payload && msg.payload.hours);
if (!Number.isFinite(hours) || hours < 1 || hours > 720) hours = 24;
msg.window_hours = hours;
msg.query = `WITH started AS (
  SELECT DISTINCT serial_number FROM process_events
  WHERE ts > now() - make_interval(hours => $1::int) AND station = 'OP10'
),
failed AS (
  SELECT DISTINCT serial_number FROM process_events
  WHERE ts > now() - make_interval(hours => $1::int) AND result = 'FAIL'
)
SELECT
  (SELECT count(*) FROM started) AS units_started,
  round(100.0 * (SELECT count(*) FROM started s
                 WHERE NOT EXISTS (SELECT 1 FROM failed f WHERE f.serial_number = s.serial_number))
        / NULLIF((SELECT count(*) FROM started), 0), 1) AS fpy_pct,
  (SELECT round(1000000.0 * count(*) FILTER (WHERE result = 'FAIL') / NULLIF(count(*), 0), 0)
     FROM process_events WHERE ts > now() - make_interval(hours => $1::int)) AS defect_ppm_ops,
  (SELECT count(*) FROM quality_events WHERE status = 'open') AS open_ncs,
  (SELECT round(100.0 * count(*) FILTER (WHERE material_lot IS NOT NULL
                                           AND gauge_id IS NOT NULL
                                           AND operator_id IS NOT NULL)
        / NULLIF(count(*), 0), 1)
     FROM process_events WHERE ts > now() - make_interval(hours => $1::int)) AS trace_coverage_pct,
  (SELECT count(DISTINCT gauge_id) FROM process_events
    WHERE gauge_cal_due < CURRENT_DATE + 30) AS gauges_cal_due_30d`;
msg.params = [hours];
return msg;

const r = (msg.payload && msg.payload[0]) || {};
const num = v => (v === null || v === undefined) ? null : Number(v);
msg.payload = {
    window_hours: msg.window_hours,
    units_started: num(r.units_started) || 0,
    first_pass_yield_pct: num(r.fpy_pct),
    defect_ppm: num(r.defect_ppm_ops),
    open_nonconformances: num(r.open_ncs) || 0,
    traceability_coverage_pct: num(r.trace_coverage_pct),
    gauges_cal_due_within_30_days: num(r.gauges_cal_due_30d) || 0
};
return msg;

