{
  "type": "object",
  "properties": {
    "days": {
      "type": "number",
      "description": "Look-back window in days (1-365)",
      "minimum": 1,
      "maximum": 365,
      "default": 7
    },
    "status": {
      "type": "string",
      "description": "Filter by NC status",
      "enum": [
        "open",
        "closed"
      ]
    },
    "station": {
      "type": "string",
      "description": "Filter by station",
      "enum": [
        "OP10",
        "OP20",
        "OP30",
        "OP40"
      ]
    },
    "defect_code": {
      "type": "string",
      "description": "Filter by defect code, e.g. LEAK-01"
    },
    "limit": {
      "type": "number",
      "description": "Max rows to return (1-500)",
      "minimum": 1,
      "maximum": 500,
      "default": 50
    }
  }
}

func:
const a = msg.payload || {};
let days = Number(a.days);
if (!Number.isFinite(days) || days < 1 || days > 365) days = 7;
let limit = Number(a.limit);
if (!Number.isFinite(limit) || limit < 1 || limit > 500) limit = 50;

const where = ['ts > now() - make_interval(days => $1::int)'];
const params = [days];
for (const [field, val] of [['status', a.status], ['station', a.station], ['defect_code', a.defect_code]]) {
    if (val) {
        params.push(String(val));
        where.push(`${field} = $${params.length}`);
    }
}
msg.query = `SELECT to_char(ts, 'YYYY-MM-DD HH24:MI') AS logged,
       serial_number, station, defect_code, description, disposition, status
FROM quality_events
WHERE ${where.join(' AND ')}
ORDER BY ts DESC
LIMIT ${limit}`;
msg.params = params;
return msg;

const a = msg.payload || {};
let days = Number(a.days);
if (!Number.isFinite(days) || days < 1 || days > 90) days = 7;
msg.query = `WITH s AS (
  SELECT serial_number, part_number, date_trunc('day', min(ts)) AS d
  FROM process_events
  WHERE ts > now() - make_interval(days => $1::int)
  GROUP BY serial_number, part_number
),
f AS (
  SELECT DISTINCT serial_number FROM process_events
  WHERE ts > now() - make_interval(days => $1::int) AND result = 'FAIL'
)
SELECT s.part_number,
       to_char(s.d, 'YYYY-MM-DD') AS day,
       count(*) AS units_started,
       round(100.0 * count(*) FILTER (WHERE f.serial_number IS NULL) / count(*), 1) AS fpy_pct
FROM s
LEFT JOIN f ON f.serial_number = s.serial_number
GROUP BY s.part_number, s.d
ORDER BY s.d, s.part_number`;
msg.params = [days];
return msg;

const lot = String((msg.payload && msg.payload.lot_id) || '').trim();
if (!lot) {
    msg.payload = { error: 'lot_id is required' };
    return [null, msg];
}
msg.lot = lot;
msg.query = `SELECT lot_id, part_family, supplier, heat_number, cert_reference,
       to_char(received_at, 'YYYY-MM-DD') AS received_at
FROM material_lots WHERE lot_id = $1`;
msg.params = [lot];
return [msg, null];

msg.lotInfo = (msg.payload && msg.payload[0]) || null;
msg.query = `SELECT p.serial_number,
       to_char(min(p.ts), 'YYYY-MM-DD HH24:MI') AS built_at,
       CASE WHEN bool_or(p.result = 'FAIL') THEN 'FAIL' ELSE 'PASS' END AS outcome
FROM process_events p
WHERE p.material_lot = $1
GROUP BY p.serial_number
ORDER BY min(p.ts)`;
msg.params = [msg.lot];
return msg;

const units = msg.payload || [];
msg.payload = {
    lot_id: msg.lot,
    found: !!msg.lotInfo,
    lot: msg.lotInfo,
    units_built: units.length,
    units_failed: units.filter(u => u.outcome === 'FAIL').length,
    units // full list -> containment scope if this lot is ever suspect
};
return msg;

// Static resource: describes the audit database so agents can reason about it
msg.payload = {
    database: 'FlowFuse Tables (PostgreSQL)',
    purpose: 'Continuous IATF 16949 traceability records for Line 3 (EWP-2201 electric water pump assembly)',
    tables: {
        process_events: {
            description: 'One row per unit per station. The core traceability record: who, what, when, measurement vs. spec, material lot, gauge and its calibration due date.',
            columns: ['id', 'ts', 'serial_number', 'part_number', 'work_order', 'station (OP10 rotor press | OP20 housing torque | OP30 leak test | OP40 EOL performance)', 'operation', 'operator_id', 'shift (A|B|C)', 'material_lot', 'gauge_id', 'gauge_cal_due', 'measurement_name', 'measurement_value', 'lsl', 'usl', 'result (PASS|FAIL)']
        },
        material_lots: {
            description: 'Incoming material genealogy: supplier, heat number and certificate reference per lot.',
            columns: ['lot_id', 'part_family', 'supplier', 'heat_number', 'cert_reference', 'received_at']
        },
        quality_events: {
            description: 'Nonconformances raised automatically when a unit fails a station.',
            columns: ['id', 'ts', 'serial_number', 'station', 'defect_code', 'description', 'disposition', 'status (open|closed)']
        }
    },
    iatf_context: 'Supports clause 8.5.2 (identification & traceability), 7.1.5 (measurement traceability / gauge calibration) and 10.2 (nonconformity and corrective action).'
};
return msg;

